node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { ExpiringStore } from './src/store.mjs';
import { TenantCache } from './src/cache.mjs';
let now = 10;
const store = new ExpiringStore({ now: () => now });
store.set('key', 'value', 5);
now = 14;
assert.deepEqual(store.get('key'), { found: true, value: 'value' });
now = 15;
assert.deepEqual(store.get('key'), { found: false });
const cache = new TenantCache(new ExpiringStore({ now: () => now }));
let calls = 0;
assert.equal(await cache.getOrLoad('a:b', 'c', () => { calls++; return false; }), false);
assert.equal(await cache.getOrLoad('a:b', 'c', () => { calls++; return 'wrong'; }), false);
assert.equal(await cache.getOrLoad('a', 'b:c', () => { calls++; return 0; }), 0);
assert.equal(calls, 2);
EOF

